spec:
NAME: pipeline;

CONTRACT Sensor:
    input boolean variable obstacle;
    output boolean variable alarm;
    Assumptions:
        true;
    Guarantees:
        G(alarm <-> obstacle);

CONTRACT Brake:
    input boolean variable alarm;
    output boolean variable stop;
    Assumptions:
        G(F(!(alarm)));
    Guarantees:
        G(alarm -> X(stop));
